tape( 'the generator can be serialized to JSON', function test( t ) {
	var json;
	var prng = xorshift32({
		'seed': 99999
	});

	xorshift32();
	json = prng.toJSON();

	t.strictEqual( typeof json, 'object', 'returns an object' );
	t.strictEqual( json.type, 'PRNG', 'has type property' );
	t.strictEqual( json.name, 'xorshift32', 'has name property' );
	t.strictEqual( Array.isArray( json.state ), true, 'has state property' );
	t.strictEqual( json.state.length, 3, 'state array has 3 elements' );
	t.end();
});

tape( 'the generator state can be restored from JSON', function test( t ) {
	var state;
	var prng1 = xorshift32({
		'seed': 99999
	});
	var prng2;
	var json;
	var i;

	// Generate some values
	for ( i = 0; i < 50; i++ ) {
		prng1();
	}

	// Serialize state
	json = prng1.toJSON();
	state = new Uint32Array( json.state );

	// Create new generator from state
	prng2 = xorshift32({
		'state': state
	});

	// Both should generate the same sequence
	for ( i = 0; i < 50; i++ ) {
		t.strictEqual( prng1(), prng2(), 'generates same value after restoration' );
	}
	t.end();
});

tape( 'the generator produces deterministic output given the same seed', function test( t ) {
	var prng1 = xorshift32({
		'seed': 12345
	});
	var prng2 = xorshift32({
		'seed': 12345
	});
	var i;

	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( prng1(), prng2(), 'generates same value for iteration '+i );
	}
	t.end();
});

tape( 'different seeds produce different sequences', function test( t ) {
	var prng1 = xorshift32({
		'seed': 111
	});
	var prng2 = xorshift32({
		'seed': 222
	});
	var same = 0;
	var v1;
	var v2;
	var i;

	for ( i = 0; i < 100; i++ ) {
		v1 = prng1();
		v2 = prng2();
		if ( v1 === v2 ) {
			same+=1;
		}
	}
	// Probability of 100 consecutive values being identical is extremely low
	t.strictEqual( same < 10, true, 'different seeds produce mostly different sequences' );
	t.end();
});

tape( 'the generator rejects zero seed', function test( t ) {
	t.throws( function f() {
		xorshift32({
			'seed': 0
		});
	}, RangeError, 'throws error for zero seed' );
	t.end();
});

tape( 'the generator accepts valid seeds (1 to 2^32-1)', function test( t ) {
	var prng1;
	var prng2;

	t.doesNotThrow( function f() {
		prng1 = xorshift32({
			'seed': 1
		});
	}, 'accepts seed = 1' );

	t.doesNotThrow( function f() {
		prng2 = xorshift32({
			'seed': UINT32_MAX
		});
	}, 'accepts seed = 2^32-1' );

	t.strictEqual( typeof prng1, 'function', 'seed 1 creates valid generator' );
	t.strictEqual( typeof prng2, 'function', 'seed 2^32-1 creates valid generator' );
	t.end();
});

tape( 'the generator rejects non-integer seeds', function test( t ) {
	t.throws( function f() {
		xorshift32({
			'seed': 3.14
		});
	}, TypeError, 'throws error for non-integer seed' );

	t.throws( function f() {
		xorshift32({
			'seed': 'not a number'
		});
	}, TypeError, 'throws error for string seed' );
	t.end();
});

tape( 'the generator seed property returns the original seed', function test( t ) {
	var retrievedSeed;
	var prng;
	var seed;

	seed = 42424;
	prng = xorshift32({
		'seed': seed
	});
	retrievedSeed = prng.seed;

	t.strictEqual( isUint32Array( retrievedSeed ), true, 'seed is Uint32Array' );
	t.strictEqual( retrievedSeed.length, 1, 'seed array has length 1' );
	t.strictEqual( retrievedSeed[ 0 ], seed, 'seed value is correct' );
	t.end();
});

tape( 'the generator state has correct structure', function test( t ) {
	var state;
	var rng;

	rng = xorshift32({
		'seed': 12345
	});
	state = rng.state;

	t.strictEqual( isUint32Array( state ), true, 'state is Uint32Array' );
	t.strictEqual( state.length, 3, 'state has 3 elements' );
	t.strictEqual( state[ 0 ], 1, 'first element is schema version (1)' );
	t.notEqual( state[ 1 ], 0, 'second element (state) is non-zero' );
	t.strictEqual( state[ 2 ], 12345, 'third element (seed) equals original seed' );
	t.end();
});

tape( 'the generator state changes after each generation', function test( t ) {
	var state1;
	var state2;
	var rng = xorshift32({
		'seed': 12345
	});

	state1 = rng.state[ 1 ];  // Get state value
	rng();
	state2 = rng.state[ 1 ];  // Get new state value

	t.notEqual( state1, state2, 'state value changes after generation' );
	t.end();
});

tape( 'xorshift32() can create independent generators', function test( t ) {
	var state;
	var rng1;
	var rng2;

	rng1 = xorshift32({
		'seed': 111
	});
	state = rng1.state;
	rng2 = xorshift32({
		'seed': 111
	});
	rng1();
	rng1.state = state;

	t.strictEqual( rng1(), rng2(), 'restoring state restores sequence alignment' );
	t.end();
});

tape( 'xorshift32() can copy state when requested', function test( t ) {
	var state = new Uint32Array( [ 1, 12345, 12345 ] );
	var rng;

	t.doesNotThrow( function f() {
		rng = xorshift32({
			'state': state,
			'copy': true
		});
	}, 'copy option works' );

	t.strictEqual( typeof rng, 'function', 'creates valid generator' );
	t.end();
});

tape( 'bit distribution should be approximately uniform', function test( t ) {
	var expectedCount;
	var percentage;
	var bitCounts;
	var tolerance;
	var samples;
	var prng;
	var i;
	var j;
	var v;

	samples = 10000;
	expectedCount = samples / 2;
	bitCounts = new Uint32Array( 32 );
	tolerance = samples * 0.05;
	prng = xorshift32({
		'seed': 42
	});

	for ( i = 0; i < samples; i++ ) {
		v = prng();
		for ( j = 0; j < 32; j++ ) {
			if ( ( v >> j ) & 1 ) {
				bitCounts[ j ] += 1;
			}
		}
	}

	for ( i = 0; i < 32; i++ ) {
		percentage = (bitCounts[i] / samples) * 100;
		t.strictEqual( abs( bitCounts[ i ] - expectedCount ) < tolerance, true, 'bit '+i+' ~50% ('+percentage.toFixed(2)+'%)' );
	}
	t.end();
});

tape( 'the generator has a toJSON method', function test( t ) {
	var rng = xorshift32({
		'seed': 12345
	});
	t.strictEqual( typeof rng.toJSON, 'function', 'has toJSON method' );
	t.end();
});

tape( 'toJSON serialization is consistent', function test( t ) {
	var json1;
	var json2;

	var rng = xorshift32({
		'seed': 12345
	});
	json1 = rng.toJSON();
	json2 = rng.toJSON();

	t.deepEqual( json1, json2, 'same state produces same JSON' );
	t.end();
});
